-- Fixed public sitemap collection; provider-specific validation remains in code.
alter table public.raven_studio_sources drop constraint if exists raven_studio_sources_provider_check;
alter table public.raven_studio_sources add constraint raven_studio_sources_provider_check
 check(provider in ('pending','ashby','greenhouse','lever','workable','smartrecruiters','bamboohr','icims','avature','jobylon','workwithindies','teamtailor','breezy','recruitee','remotegamejobs','blenderartists','epicforum','artstation','hitmarker'));

insert into public.raven_studio_sources(studio_name,slug,provider,board_key,careers_url,source_kind,segment,segment_note,verification_status,verification_note,priority,interval_hours,source_verified_at,next_check_at) values
('Hitmarker','hitmarker','hitmarker','hitmarker','https://hitmarker.net/jobs','job_board','unknown','Public sitemap discovery; sitemap URLs are not verified active vacancies. Targeted descriptions rotate12 per scan; coverage remains partial until checked. Actual role employers and remote restrictions retained.','verified','Official public sitemap index advertises3 job sitemaps containing14432URLs,174 target slug candidates. Anonymous server-rendered job details provide canonical URL, JobPosting identity and visible activity marker. No gated search credentials used. docs/board-hitmarker-verification.json.',3,6,now(),now()),
('GameJobs.co','gamejobs-co','pending',null,'https://gamejobs.co/','job_board','unknown','Manual discovery only; direct automated access blocked. Indexed listings may be stale; primary employer validation required.','blocked','Direct root,wwwroot and indexed detail requests403. Search indexing does not establish a working collector. Indexed Singularity6 temporary role rejected by actual employer Job not found response. docs/board-gamejobs-verification.json and board-gamejobs-primary-fallback.json.',1,168,null,now()),
('Grackle HQ','grackle-hq','pending',null,'https://gracklehq.com/jobs?metro=Remote','job_board','unknown','Manual studio/source discovery. Grackle redirects to external postings rather than hosting descriptions; current supported feeds cover sampled matches.','unsupported','Public remote list200 advertises255results with30cards on observedpage. Same-host rd endpoints302 to WWI or verified BlackbirdLever source; no hosted descriptions/API established. Redirect destinations inspected but not followed. docs/board-grackle-verification.json.',1,168,null,now())
on conflict(slug) do update set provider=excluded.provider,board_key=excluded.board_key,careers_url=excluded.careers_url,source_kind=excluded.source_kind,segment=excluded.segment,segment_note=excluded.segment_note,verification_status=excluded.verification_status,verification_note=excluded.verification_note,source_verified_at=excluded.source_verified_at,interval_hours=excluded.interval_hours,next_check_at=now(),enabled=true;
